def pageName = "home";
List counts = query(db,"select from pageCount where name='${pageName}'");
int count = 1;
if (counts.size() == 0) {
  update(db,"insert into pageCount set name='${pageName}', count=${count}");
} else { 
  count = counts[0].fromJson().count + 1;
  update(db,"update pageCount set count=${count} where name='${pageName}'");
};
return count;
